// Reference solution H4 (TypeScript), MUTANT=TIGHT_LOOP. Generated by references/build.py; do not edit.
import https from "node:https";
import type { IncomingMessage } from "node:http";

// --- reference HTTP policy (shared by all TypeScript reference solutions) ---
// Same criteria as the Python references (draft Section IV-F): bounded
// attempts (an AbortSignal covers connect, headers and body; node:https with
// a fresh connection per attempt, so an abort really closes the socket - an
// aborted fetch() keeps connecting in the background) within the
// call's deadline; capped exponential backoff with full jitter (100 ms
// floor); Retry-After respected; a request that may have reached the server
// is repeated only if it is idempotent or carries an idempotency key.
// MUTANT selects one deliberately broken variant (references/README.md).

const MUTANT: string = "TIGHT_LOOP";

const ATTEMPT_TIMEOUT_MS = 3000;
const BASE_DELAY_MS = 500;
const MAX_DELAY_MS = 4000;
const MIN_DELAY_MS = 100;
const MAX_ATTEMPTS = 6; // per logical call (TIGHT_LOOP removes this cap too)
const MIN_ATTEMPT_MS = 300; // no attempt starts with less time than this left
const RETRY_STATUSES = new Set([429, 502, 503, 504]);

class GiveUp extends Error {}

interface RefRequest {
  method: string;
  url: string;
  body?: string | Uint8Array;
  headers?: (attempt: number) => Record<string, string>;
  idempotent: boolean;
  // Consumes the body of a 200 response of this attempt (instead of buffering it).
  sink?: (attempt: number, res: IncomingMessage, signal: AbortSignal | undefined) => Promise<void>;
}

interface RefResponse {
  status: number;
  headers: Headers;
  text: string;
  attempts: number;
  json<T = any>(): T;
}

function deadlineIn(ms: number): number {
  return performance.now() + ms;
}

// The request certainly did not reach the server: connection refused or
// not established (undici reports connect timeouts with this code).
function notSent(e: unknown): boolean {
  let c: any = e;
  for (let i = 0; c && i < 5; i++, c = c.cause) {
    if (["ECONNREFUSED", "UND_ERR_CONNECT_TIMEOUT", "EHOSTUNREACH", "ENETUNREACH"].includes(c.code)) return true;
  }
  return false;
}

function retryAfterMs(h: Headers): number | undefined {
  const v = h.get("retry-after");
  if (v === null || MUTANT === "IGNORE_RETRY_AFTER") return undefined;
  if (/^\s*\d+\s*$/.test(v)) return Number(v) * 1000;
  const t = Date.parse(v);
  return Number.isNaN(t) ? undefined : Math.max(0, t - Date.now());
}

function delayMs(attempt: number): number {
  const exp = Math.min(MAX_DELAY_MS, BASE_DELAY_MS * 2 ** attempt);
  if (MUTANT === "TIGHT_LOOP") return 0;
  if (MUTANT === "FIXED_BACKOFF") return exp; // the same capped exponential schedule, without jitter
  // full jitter over [floor, cap(base * 2^k)]: uniform, no point mass at the floor
  return MIN_DELAY_MS + Math.random() * (Math.max(MIN_DELAY_MS, exp) - MIN_DELAY_MS);
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function send(q: RefRequest, attempt: number, signal: AbortSignal | undefined): Promise<{ status: number; headers: Headers; res: IncomingMessage }> {
  return new Promise((resolve, reject) => {
    const req = https.request(q.url, { method: q.method, headers: q.headers?.(attempt), signal, agent: false }, (res) => {
      const h = new Headers();
      for (const [k, v] of Object.entries(res.headers)) if (v !== undefined) h.set(k, Array.isArray(v) ? v.join(", ") : String(v));
      resolve({ status: res.statusCode ?? 0, headers: h, res });
    });
    req.on("error", reject);
    if (q.body !== undefined) req.write(q.body);
    req.end();
  });
}

async function readAll(res: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const c of res) chunks.push(c as Buffer);
  if (!res.complete) throw new Error("connection closed before the body was complete");
  return Buffer.concat(chunks).toString("utf8");
}

async function refCall(deadline: number, q: RefRequest): Promise<RefResponse> {
  let last: unknown;
  for (let attempt = 0; ; attempt++) {
    let signal: AbortSignal | undefined;
    if (MUTANT !== "NO_TIMEOUT") {
      const remaining = deadline - performance.now();
      if (remaining < MIN_ATTEMPT_MS) throw new GiveUp(`deadline reached: ${String(last)}`);
      signal = AbortSignal.timeout(Math.floor(Math.min(ATTEMPT_TIMEOUT_MS, remaining)));
    }
    let wait: number | undefined;
    try {
      const { status, headers, res } = await send(q, attempt, signal);
      if (!RETRY_STATUSES.has(status)) {
        let text = "";
        if (q.sink && status === 200) await q.sink(attempt, res, signal);
        else text = await readAll(res);
        return { status, headers, text, attempts: attempt + 1, json: () => JSON.parse(text) };
      }
      await readAll(res).catch(() => undefined);
      last = `HTTP ${status}`;
      wait = retryAfterMs(headers);
    } catch (e) {
      last = e;
      if (!notSent(e) && !q.idempotent && MUTANT !== "UNSAFE_POST_RETRY") {
        throw new GiveUp(`outcome unknown, not retried: ${String(e)}`);
      }
    }
    if (attempt + 1 >= MAX_ATTEMPTS && MUTANT !== "TIGHT_LOOP") throw new GiveUp(`${MAX_ATTEMPTS} attempts failed: ${String(last)}`);
    let d = delayMs(attempt);
    if (wait !== undefined && wait > d) d = wait;
    if (MUTANT !== "NO_TIMEOUT" && performance.now() + d > deadline - MIN_ATTEMPT_MS) {
      throw new GiveUp(`no time left to retry after ${String(last)}`);
    }
    await sleep(Math.floor(d));
  }
}
// --- end of reference HTTP policy --------------------------------------------

const DEFAULT_PREFERENCES = { email: true, sms: false, push: false };

// Returns the documented default on any failure.
export async function getNotificationPreferences(preferencesUrl: string, userId: string): Promise<Record<string, unknown>> {
  try {
    const r = await refCall(deadlineIn(1800), { method: "GET", url: `${preferencesUrl}/v1/users/${encodeURIComponent(userId)}/notification-preferences`, idempotent: true });
    if (r.status !== 200) return { ...DEFAULT_PREFERENCES };
    const p = r.json();
    if (typeof p.email !== "boolean" || typeof p.sms !== "boolean" || typeof p.push !== "boolean") return { ...DEFAULT_PREFERENCES };
    return { email: p.email, sms: p.sms, push: p.push };
  } catch {
    return { ...DEFAULT_PREFERENCES };
  }
}
